SELECT DATE_TRUNC('QUARTER', opened_date) AS quarter_start, city, SUM(CASE WHEN region = 'East' THEN sqft ELSE 0 END) AS east_sqft, PERCENTILE_APPROX(sqft, 0.9) AS sqft_p90, ROUND(SUM(sqft) / NULLIF(COUNT(CASE WHEN region = 'East' THEN 1 END), 0), 2) AS sqft_per_east, AVG(sqft) FILTER (WHERE region = 'South') AS south_avg_sqft FROM stores GROUP BY DATE_TRUNC('QUARTER', opened_date), city
